import os, base64
R = "LockCOC" if os.path.isdir("LockCOC") else "."
def P(p): return os.path.join(R, p)
V = ''
J = ''
if os.path.exists(P("static/downloads/intro5.mp4")): raise SystemExit("[loi] da ap dung patch43 roi")
os.makedirs(P("static/downloads"), exist_ok=True)
open(P("static/downloads/intro5.mp4"), "wb").write(base64.b64decode(V))
open(P("static/downloads/intro5.jpg"), "wb").write(base64.b64decode(J))
n = 0
for root, _, fs in os.walk(R):
    if ".git" in root or "node_modules" in root: continue
    for f in fs:
        if not f.endswith((".html", ".js", ".css")): continue
        p = os.path.join(root, f)
        try: s = open(p, encoding="utf-8").read()
        except Exception: continue
        t = s
        for a, b in (("intro4.mp4", "intro5.mp4"), ("intro3.mp4", "intro5.mp4"), ("intro2.mp4", "intro5.mp4"), ("intro4.jpg", "intro5.jpg"), ("intro3.jpg", "intro5.jpg"), ("intro2.jpg", "intro5.jpg"), ("demo.mp4", "intro5.mp4"), ("demo-poster.jpg", "intro5.jpg")): t = t.replace(a, b)
        if t != s: open(p, "w", encoding="utf-8").write(t); n += 1
print("[ok] patch43 xong: video gioi thieu moi, da cap nhat %d file" % n)
if n == 0: print("[canh bao] khong thay cho gan video trong landing")

import re
lp = P("templates/landing.html")
L = open(lp, encoding="utf-8").read()
L2 = re.sub(r"<([a-zA-Z0-9]+)[^>]*>[^<]*Ảnh và dữ liệu trong video là mẫu[^<]*</\1>", "", L)
L2 = L2.replace("Ảnh và dữ liệu trong video là mẫu.", "").replace("Ảnh và dữ liệu trong video là mẫu", "")
if L2 != L: open(lp, "w", encoding="utf-8").write(L2); print("[ok] da xoa chu 'la mau' tren trang")
